window.SantaUIText = [["NORTH POLE","NORDPOLEN","NORDPOLEN"],["INVENTOR CLUB","OPFINDERKLUB","UPPFINNARKLUBBEN"],["The story","Historien","Berättelsen"],["Install","Installér","Installera"],["Golden Rules","Gyldne regler","Gyllene regler"],["12 MISSIONS. ONE VERY MESSY NORTH POLE.","12 MISSIONER. ÉN MEGET RODET NORDPOL.","12 UPPDRAG. EN MYCKET STÖKIG NORDPOL."],["Santa's","Julemandens","Tomtens"],["Secret Missions","Hemmelige missioner","Hemliga uppdrag"],["The elves have made a little mess.","Nisserne har rodet lidt.","Nissarna har stökat till det lite."],["Okay… a","Okay… et","Okej… ett"],["spectacular","spektakulært","spektakulärt"],["mess.","rod.","kaos."],["Your ideas + a little AI magic can save Christmas.","Dine idéer + lidt AI-magi kan redde julen.","Dina idéer + lite AI-magi kan rädda julen."],["Welcome, Agent","Velkommen, agent","Välkommen, agent"],["P.S. Don't tell Kevin.","P.S. Sig det ikke til Kevin.","P.S. Säg inget till Kevin."],["North Pole Chaos Resolved","Nordpolens kaos løst","Nordpolens kaos löst"],["Twelve tiny doors. Big inventor energy.","Tolv små døre. Store opfinderidéer.","Tolv små dörrar. Stora uppfinnaridéer."],["THE WORKSHOP VILLAGE","VÆRKSTEDSBYEN","VERKSTADSBYN"],["December 2026","December 2026","December 2026"],["A secret mission every other day","En hemmelig mission hver anden dag","Ett hemligt uppdrag varannan dag"],["✦ Christmas saved. Inventor certified. ✦","✦ Julen er reddet. Officielt opfinder! ✦","✦ Julen är räddad. Certifierad uppfinnare! ✦"],["Open the door →","Åbn døren →","Öppna dörren →"],["Santa has a workshop upgrade ready.","Julemanden har en opdatering klar.","Tomten har en uppdatering klar."],["Update app","Opdatér appen","Uppdatera appen"],["TEST MODE — ALL DOORS UNLOCKED","TESTTILSTAND — ALLE DØRE ÅBNE","TESTLÄGE — ALLA DÖRRAR ÖPPNA"],["A little imagination. A little AI. A lot of Christmas chaos.","Lidt fantasi. Lidt AI. Masser af julekaos.","Lite fantasi. Lite AI. Massor av julkaos."],["Made for curious minds. Approved by Santa. Absolutely not approved by Kevin.","Til nysgerrige hoveder. Godkendt af julemanden. Absolut ikke af Kevin.","För nyfikna hjärnor. Godkänt av tomten. Absolut inte av Kevin."],["Read the story & change agent name","Læs historien og skift agentnavn","Läs berättelsen och byt agentnamn"],["Santa's Golden Rules","Julemandens gyldne regler","Tomtens gyllene regler"],["Stars and creations stay on this device. Keep your original HTML files as a backup.","Stjerner og opfindelser gemmes kun på denne enhed. Behold dine originale HTML-filer.","Stjärnor och skapelser sparas på den här enheten. Behåll originalfilerna som säkerhetskopia."],["Install & offline help","Installation og offlinehjælp","Installation och offlinehjälp"],["Preparing offline magic…","Forbereder offline-magi…","Förbereder offline-magi…"],["TEST MODE — all 12 doors unlocked on this device.","TESTTILSTAND — alle 12 døre er åbne på denne enhed.","TESTLÄGE — alla 12 dörrar är öppna på den här enheten."],["Test stars and creations are kept separate.","Teststjerner og -filer gemmes separat.","Teststjärnor och skapelser sparas separat."],["Return to real calendar","Tilbage til den rigtige kalender","Tillbaka till riktiga kalendern"],["← Back to the village","← Tilbage til byen","← Tillbaka till byn"],["NORTH POLE • TOP SECRET","NORDPOLEN • TOPHEMMELIGT","NORDPOLEN • TOPPHEMLIGT"],["Your AI superpower:","Din AI-superkraft:","Din AI-superkraft:"],["INCOMING FROM SANTA","BESKED FRA JULEMANDEN","MEDDELANDE FRÅN TOMTEN"],["— Santa Claus","— Julemanden","— Jultomten"],["About 20–40 minutes of creative mischief","Ca. 20–40 minutters kreativ ballade","Cirka 20–40 minuter kreativt bus"],["FINAL OUTPUT","DET ENDELIGE RESULTAT","SLUTRESULTAT"],["One complete standalone HTML file.","Én komplet, selvstændig HTML-fil.","En komplett, fristående HTML-fil."],["Your secret assignment","Din hemmelige opgave","Ditt hemliga uppdrag"],["✧ BONUS CHALLENGE · OPTIONAL","✧ BONUSOPGAVE · VALGFRI","✧ BONUSUTMANING · VALFRITT"],["✧ Santa's Golden Rules","✧ Julemandens gyldne regler","✧ Tomtens gyllene regler"],["Help! I'm Stuck!","Hjælp! Jeg sidder fast!","Hjälp! Jag har fastnat!"],["Your inventor's workbench","Dit opfinderværksted","Din uppfinnarverkstad"],["Bring your HTML creation here and give it a test run.","Upload din HTML-opfindelse her, og prøv den af.","Ladda upp din HTML-skapelse här och prova den."],["Only on this device. Your file is never uploaded to a server.","Kun på denne enhed. Filen sendes aldrig til en server.","Bara på den här enheten. Filen skickas aldrig till en server."],["Upload My Creation","Upload min opfindelse","Ladda upp min skapelse"],["Open My Creation →","Åbn min opfindelse →","Öppna min skapelse →"],["Replace Creation","Udskift opfindelse","Byt ut skapelse"],["Download Creation","Hent opfindelse","Ladda ned skapelse"],["Delete Creation","Slet opfindelse","Ta bort skapelse"],["Keep the original HTML file in Files or Downloads. These local copies may be lost if website data is cleared or the app is removed. Uploading or deleting a file never changes your mission's star.","Behold den originale HTML-fil i Filer eller Downloads. Lokale kopier kan forsvinde, hvis appen eller webstedsdata slettes. Upload og sletning ændrer aldrig missionens stjerne.","Behåll originalfilen i Filer eller Hämtade filer. Lokala kopior kan försvinna om appen eller webbplatsdata raderas. Uppladdning och radering påverkar aldrig uppdragets stjärna."],["Creation tested? Improvement made?","Testet din opfindelse? Forbedret noget?","Testat din skapelse? Förbättrat något?"],["When you're happy with your invention, give yourself a well-earned star. Santa trusts you. No file upload is required.","Når du er tilfreds med opfindelsen, må du give dig selv en velfortjent stjerne. Julemanden stoler på dig. Upload er ikke påkrævet.","När du är nöjd med din uppfinning får du ge dig själv en välförtjänt stjärna. Tomten litar på dig. Du behöver inte ladda upp någon fil."],["☆ Mission Completed!","☆ Mission fuldført!","☆ Uppdrag slutfört!"],["★ Mission Completed!","★ Mission fuldført!","★ Uppdrag slutfört!"],["Oops! Unmark this mission","Ups! Fjern markeringen","Hoppsan! Ångra markeringen"],["A golden star, earned by you.","En guldstjerne, du selv har fortjent.","En guldstjärna som du har förtjänat."],["THE INVENTOR'S POCKET HANDBOOK","OPFINDERENS LOMMEHÅNDBOG","UPPFINNARENS HANDBOK"],["You bring the ideas. AI helps you make them real.","Du kommer med idéerne. AI hjælper med at bygge dem.","Du kommer med idéerna. AI hjälper dig förverkliga dem."],["CHAT","CHAT","CHATTA"],["PLAN","PLANLÆG","PLANERA"],["BUILD","BYG","BYGG"],["TEST","TEST","TESTA"],["IMPROVE","FORBEDR","FÖRBÄTTRA"],["Take Me to the Village →","Tag mig til byen →","Ta mig till byn →"],["Back to my mission →","Tilbage til min mission →","Tillbaka till mitt uppdrag →"],["Back to the Village →","Tilbage til byen →","Tillbaka till byn →"],["Use ordinary ChatGPT Chat to discuss and plan. Work can help build when it's available. Free ChatGPT works too — you don't need a paid subscription to take part.","Brug en almindelig ChatGPT-chat til at tale og planlægge. Work kan hjælpe med at bygge, hvis det er tilgængeligt. Gratis ChatGPT kan også bruges.","Använd en vanlig ChatGPT-chatt för att diskutera och planera. Work kan hjälpa till att bygga, om det finns. Gratis ChatGPT fungerar också."],["You can read your missions and plan with AI on your phone or computer.","Du kan læse missionerne og planlægge med AI på mobil eller computer.","Du kan läsa uppdragen och planera med AI på mobil eller dator."],["You can also import and test ordinary HTML creations inside Santa's Secret Missions.","Du kan også importere og afprøve HTML-opfindelser inde i kalenderen.","Du kan också importera och prova HTML-skapelser direkt i kalendern."],["For more advanced projects, a computer browser may work better.","Til større projekter kan en computerbrowser være nemmere.","För mer avancerade projekt kan en dator fungera bättre."],["SANTA'S INVENTOR HELPLINE","JULEMANDENS OPFINDERHJÆLP","TOMTENS UPPFINNARHJÄLP"],["Even elves need a little help.","Selv nisser har brug for lidt hjælp.","Till och med nissar behöver lite hjälp."],["Start small. Reveal more only when you need it.","Start med lidt hjælp. Få mere frem, hvis du har brug for det.","Börja med lite hjälp. Visa mer när du behöver det."],["A little nudge","Et lille hint","En liten ledtråd"],["The building plan","Byggeplanen","Byggplanen"],["Rescue prompt","Redningsprompt","Räddningsprompt"],["Santa’s building plan","Julemandens byggeplan","Tomtens byggplan"],["Emergency Rescue Prompt","Nød-redningsprompt","Akut räddningsprompt"],["Paste this into ChatGPT Chat.","Indsæt dette i en ChatGPT-chat.","Klistra in detta i en ChatGPT-chatt."],["Free or Work — your ideas are what matter.","Gratis eller Work — dine idéer er vigtigst.","Gratis eller Work — dina idéer är viktigast."],["Copy Prompt","Kopiér prompt","Kopiera prompt"],["Copied! ✓","Kopieret! ✓","Kopierat! ✓"],["← Previous hint","← Forrige hint","← Föregående ledtråd"],["A little more help →","Lidt mere hjælp →","Lite mer hjälp →"],["Show the rescue prompt →","Vis redningsprompten →","Visa räddningsprompten →"],["Using a hint doesn't cost you a star. Inventors ask for help!","Du mister ikke en stjerne af at bruge hints. Opfindere beder om hjælp!","Du förlorar ingen stjärna för att du använder ledtrådar. Uppfinnare ber om hjälp!"],["A VERY SECRET RECRUITMENT LETTER","ET MEGET HEMMELIGT BREV","ETT MYCKET HEMLIGT BREV"],["You're on Santa's secret team.","Du er med på julemandens hemmelige hold.","Du är med i tomtens hemliga team."],["What should Santa call you?","Hvad skal julemanden kalde dig?","Vad ska tomten kalla dig?"],["Save name","Gem navn","Spara namn"],["YOUR INVENTOR KIT","DIT OPFINDERUDSTYR","DITT UPPFINNARKIT"],["✦ Open a new door every other day, December 1–23.","✦ Åbn en ny dør hver anden dag fra 1. til 23. december.","✦ Öppna en ny dörr varannan dag den 1–23 december."],["✦ Plan with AI, build your idea, then test and improve it.","✦ Planlæg med AI, byg din idé, test og forbedr den.","✦ Planera med AI, bygg din idé, testa och förbättra."],["✦ Save your creation as one HTML file. Import it here to try it, then mark the mission complete yourself.","✦ Gem din opfindelse i én HTML-fil. Importér og test den her. Markér selv missionen som fuldført.","✦ Spara din skapelse som en HTML-fil. Importera och testa den här och markera sedan uppdraget som klart."],["✦ Need a hand? Santa's Golden Rules and three hints are always nearby.","✦ Brug for hjælp? Julemandens gyldne regler og tre hints er altid lige ved hånden.","✦ Behöver du hjälp? Tomtens gyllene regler och tre ledtrådar finns alltid nära."],["Take Me to Santa's Golden Rules →","Vis mig julemandens gyldne regler →","Visa mig tomtens gyllene regler →"],["Your name, stars and imported creations stay on this device. No account, tracking or grading. Keep your original HTML files as a backup.","Dit navn, dine stjerner og filer bliver på denne enhed. Ingen konto, sporing eller karakterer. Behold originale HTML-filer som backup.","Ditt namn, dina stjärnor och importerade filer stannar på den här enheten. Inget konto, ingen spårning, inga betyg. Behåll originalfilerna."],["YOUR CREATION · ISOLATED PREVIEW","DIN OPFINDELSE · ISOLERET FORHÅNDSVISNING","DIN SKAPELSE · ISOLERAD FÖRHANDSVISNING"],["Your creation","Din opfindelse","Din skapelse"],["Restart","Start forfra","Starta om"],["Expand","Udvid","Förstora"],["Back to mission","Tilbage til missionen","Tillbaka till uppdraget"],["Remove this local copy?","Fjern den lokale kopi?","Ta bort den lokala kopian?"],["Your original file in Files or Downloads stays safe. Your mission star stays exactly as it is.","Din originale fil i Filer eller Downloads bliver ikke slettet. Din missionsstjerne påvirkes ikke.","Din originalfil i Filer eller Hämtade filer påverkas inte. Din uppdragsstjärna ändras inte."],["Keep my creation","Behold min opfindelse","Behåll min skapelse"],["Delete local copy","Slet lokal kopi","Ta bort lokal kopia"],["POCKET-SIZED NORTH POLE","NORDPOLEN I LOMMEFORMAT","NORDPOLEN I FICKFORMAT"],["Give Santa a Home Screen.","Få julemanden på hjemmeskærmen.","Ge tomten en plats på hemskärmen."],["Your calendar works in a normal browser, too. Installing it gives your missions a little home of their own.","Kalenderen virker også i en normal browser. Installér den for at få den på hjemmeskærmen.","Kalendern fungerar också i webbläsaren. Installera den för att få uppdragen på hemskärmen."],["On iPhone or iPad","På iPhone eller iPad","På iPhone eller iPad"],["Open this website in","Åbn hjemmesiden i","Öppna webbplatsen i"],["Tap","Tryk på","Tryck på"],["Choose","Vælg","Välj"],["if offered.","hvis du får muligheden.","om alternativet visas."],["Add","Tilføj","Lägg till"],["On Android or a computer","På Android eller computer","På Android eller dator"],["Use your browser's","Brug browserens","Använd webbläsarens"],["option. If this browser offers an install button below, you can use it.","mulighed. Hvis du ser en installationsknap herunder, kan du bruge den.","alternativ. Om webbläsaren visar en installationsknapp nedan kan du använda den."],["Install Santa's Secret Missions","Installér julemandens hemmelige missioner","Installera tomtens hemliga uppdrag"],["Take the magic offline","Tag magien med offline","Ta med magin offline"],["Keep your inventions safe","Pas på dine opfindelser","Skydda dina uppfinningar"],["New missions","Nye missioner","Nya uppdrag"],["When you return, Santa highlights any new mission waiting for you. This version doesn't send push notifications.","Når du vender tilbage, viser julemanden nye missioner. Denne version sender ikke push-notifikationer.","När du kommer tillbaka markerar tomten nya uppdrag. Den här versionen skickar inga pushnotiser."]];

window.SantaUIText.push(...[["Christmas officially saved. Kevin is speechless.","Julen er reddet! Kevin er målløs.","Julen är räddad! Kevin är mållös."],["Twelve tiny doors. Big inventor energy.","Tolv små døre. Store opfinderidéer.","Tolv små dörrar. Stora uppfinnaridéer."],["The workshop is getting its sparkle back.","Værkstedet begynder at stråle igen.","Verkstaden börjar glittra igen."],["Santa is calling this a Christmas miracle.","Julemanden kalder det et julemirakel.","Tomten kallar det ett julmirakel."],["✦ TOP SECRET! A new mission is waiting for you.","✦ TOPHEMMELIGT! En ny mission venter på dig.","✦ TOPPHEMLIGT! Ett nytt uppdrag väntar på dig."],["Mission","Mission","Uppdrag"],["Completed","Fuldført","Slutfört"],["New mission available","Ny mission klar","Nytt uppdrag tillgängligt"],["Available","Klar","Tillgängligt"],["Locked","Låst","Låst"],["Open mission.","Åbn missionen.","Öppna uppdraget."],["Saved on this device","Gemt på denne enhed","Sparat på den här enheten"],["A little local workshop magic…","Lidt lokal værkstedsmagi…","Lite lokal verkstadsmagi…"],["Saved here on your device. Ready for a test run! Your mission star is unchanged.","Gemt på din enhed. Klar til at prøve! Din stjerne er uændret.","Sparat på din enhet. Redo att provas! Din stjärna är oförändrad."],["Local copy deleted. Your original file and mission star are unchanged.","Den lokale kopi er slettet. Din originale fil og stjerne er uændrede.","Den lokala kopian är borttagen. Din originalfil och stjärna är kvar."],["Local copy removed. Your mission star is safe.","Den lokale kopi er fjernet. Din stjerne er sikker.","Den lokala kopian är borttagen. Din stjärna är säker."],["Rescue prompt copied. Paste it into ChatGPT Chat to start planning.","Redningsprompten er kopieret. Indsæt den i ChatGPT for at planlægge.","Räddningsprompten är kopierad. Klistra in den i ChatGPT och börja planera."],["Automatic copying is unavailable. The prompt is selected — use Ctrl+C / ⌘C, or touch and hold to copy it.","Automatisk kopiering virker ikke. Prompten er markeret – brug Ctrl+C / ⌘C eller hold fingeren nede for at kopiere.","Automatisk kopiering fungerar inte. Prompten är markerad – tryck Ctrl+C / ⌘C eller håll fingret nedtryckt för att kopiera."],["Santa is on your Home Screen. Ready for your next invention!","Julemanden er på din hjemmeskærm. Klar til næste opfindelse!","Tomten finns på hemskärmen. Redo för nästa uppfinning!"],["Use your browser’s Install app or Add to Home Screen option.","Brug browserens 'Installér app' eller 'Føj til hjemmeskærm'.","Använd webbläsarens 'Installera app' eller 'Lägg till på hemskärmen'."],["Return from your creation preview before updating the calendar. Your saved HTML file will stay safe.","Luk forhåndsvisningen, før du opdaterer kalenderen. Din gemte HTML-fil bevares.","Stäng förhandsvisningen innan du uppdaterar kalendern. Din sparade HTML-fil är kvar."],["Close your creation preview, then update. Saved files stay safe.","Luk forhåndsvisningen, og opdatér derefter. Gemte filer bevares.","Stäng förhandsvisningen och uppdatera sedan. Sparade filer finns kvar."],["Updating…","Opdaterer…","Uppdaterar…"],["Open the HTTPS website to enable installation and offline access.","Åbn HTTPS-hjemmesiden for at installere og bruge offline.","Öppna HTTPS-webbplatsen för installation och offlineåtkomst."],["Ready offline · your workshop can travel with you.","Klar til offline · dit værksted kan komme med dig.","Redo offline · ta med verkstaden överallt."],["Calendar ready. Offline setup couldn’t finish — open it online again to retry.","Kalenderen er klar. Offlineopsætningen blev ikke færdig – prøv igen med internet.","Kalendern är klar. Offlineläget kunde inte aktiveras – prova igen med internet."],["Test build · installation and offline caching use the production app.","Testversion · installation og offlinecache bruger produktionsappen.","Testversion · installation och offlinecache använder den riktiga appen."],["Even elves need a little help.","Selv nisser har brug for lidt hjælp.","Till och med nissar behöver lite hjälp."]]);

